export const svgColor=value=>typeof value==='string'&&/^#(?:[\da-f]{3}|[\da-f]{4}|[\da-f]{6}|[\da-f]{8})$/i.test(value);
export function svgAttributes(text){
 if(typeof text!=='string'||text.length>1000000||!/<svg\b/i.test(text)||/<(?:script|style|foreignObject)\b|<!DOCTYPE|<!ENTITY/i.test(text))throw Error('이 SVG 형식은 아직 색상 편집을 지원하지 않습니다.');
 const result=[];for(const tag of text.matchAll(/<[A-Za-z][^>]*>/g)){for(const m of tag[0].matchAll(/(?:^|\s)(fill|stroke|stop-color)\s*=\s*(["'])(#[\da-f]+)\2/gi)){if(svgColor(m[3])){const start=tag.index+m.index+m[0].indexOf(m[2])+1;result.push({attribute:m[1].toLowerCase(),value:m[3],start,end:start+m[3].length});}}}return result;
}
export function svgSlots(text){const groups=new Map();svgAttributes(text).forEach((a,index)=>{const key=a.attribute+':'+a.value.toLowerCase();if(!groups.has(key))groups.set(key,{attribute:a.attribute,value:a.value,indices:[]});groups.get(key).indices.push(index);});return [...groups.values()].map((s,i)=>({...s,key:s.indices.join(','),label:s.attribute==='stop-color'?(groups.size===2&&[...groups.values()].every(g=>g.attribute==='stop-color')?(i===0?'그라데이션 시작색':'그라데이션 끝색'):`그라데이션 색상 ${i+1}`):s.attribute==='stroke'?`윤곽선 색상 ${i+1}`:`로고 색상 ${i+1}`}));}
export function patchSvg(text,changes){const attrs=svgAttributes(text),slots=svgSlots(text),edits=[];for(const change of changes){if(!svgColor(change.value))throw Error('SVG 색상은 HEX로 지정하세요.');const slot=slots.find(s=>s.key===change.slot);if(!slot)throw Error('SVG 색상 위치가 변경되었습니다. 다시 선택하세요.');for(const i of slot.indices)edits.push({...attrs[i],value:change.value});}if(new Set(edits.map(e=>e.start)).size!==edits.length)throw Error('중복된 SVG 색상 변경입니다.');for(const e of edits.sort((a,b)=>b.start-a.start))text=text.slice(0,e.start)+e.value+text.slice(e.end);return text;}
